"""schemas.py

Pydantic schemas for the Agentic Risk Gatekeeper microservice.
"""

from __future__ import annotations

from datetime import datetime
from typing import Any, List, Literal, Optional
from pydantic import BaseModel, Field, field_validator


class SignalRequest(BaseModel):
    """Incoming statistical arbitrage pairs-trading signal generated by the quant engine."""

    ticker_a: str = Field(
        ...,
        description="Ticker symbol for the first leg of the pair (e.g. 'AAPL')",
        min_length=1,
        max_length=10,
    )
    ticker_b: str = Field(
        ...,
        description="Ticker symbol for the second leg of the pair (e.g. 'MSFT')",
        min_length=1,
        max_length=10,
    )
    signal_timestamp: datetime = Field(
        ...,
        description="The exact point-in-time timestamp when the quant model triggered the signal (UTC)",
    )
    z_score: float = Field(
        ...,
        description="Current spread divergence z-score (e.g. +2.4 or -2.1)",
    )

    @field_validator("ticker_a", "ticker_b")
    @classmethod
    def normalize_ticker(cls, v: str) -> str:
        return v.strip().upper().replace(".", "-")

    @field_validator("signal_timestamp")
    @classmethod
    def ensure_timezone_aware(cls, v: datetime) -> datetime:
        from datetime import timezone
        if v.tzinfo is None:
            # Assume UTC if naive
            return v.replace(tzinfo=timezone.utc)
        return v


class FilingChunk(BaseModel):
    """Metadata and content for an SEC filing or transcript chunk retrieved from Qdrant."""

    chunk_id: str
    ticker: str
    document_id: str
    accession_number: Optional[str] = None
    form_type: Optional[str] = None
    section_type: Optional[str] = None
    item_code: Optional[str] = None
    available_at: str
    published_at: Optional[str] = None
    text: str
    score: Optional[float] = None


class GatekeeperResponse(BaseModel):
    """Structured decision returned by the Agentic Risk Gatekeeper."""

    decision: Literal["GO", "VETO"] = Field(
        ...,
        description="GO clears the signal for execution; VETO aborts the trade due to fundamental risk",
    )
    confidence_score: float = Field(
        ...,
        ge=0.0,
        le=1.0,
        description="Confidence in the risk assessment from 0.0 (uncertain) to 1.0 (absolute certainty)",
    )

    @field_validator("confidence_score", mode="before")
    @classmethod
    def normalize_confidence(cls, v: Any) -> float:
        if isinstance(v, str):
            v_clean = v.strip().rstrip("%")
            try:
                val = float(v_clean)
                if "%" in v or val > 1.0:
                    val = val / 100.0
                return val
            except ValueError:
                pass
        return v
    risk_category: Literal[
        "none",
        "legal_regulatory",
        "financial_distress",
        "executive_governance",
        "operational",
    ] = Field(
        ...,
        description="Primary category of identified fundamental risk, or 'none' if cleared",
    )
    justification: str = Field(
        ...,
        min_length=5,
        description="Concise rationale citing specific filing evidence or stating why risk is cleared",
    )
    filing_ids_inspected: List[str] = Field(
        default_factory=list,
        description="List of chunk IDs or accession numbers inspected during evaluation",
    )

    # ── Monte Carlo Simulation Diagnostics (optional) ──────────────────────────
    simulation_performed: bool = Field(
        default=False,
        description="Whether a Monte Carlo OU simulation was executed for this signal",
    )
    convergence_probability: Optional[float] = Field(
        default=None,
        ge=0.0,
        le=1.0,
        description=(
            "Fraction of simulated OU paths that revert to |z| <= 0.5 within the "
            "horizon (higher = more likely to mean-revert)"
        ),
    )
    breach_probability: Optional[float] = Field(
        default=None,
        ge=0.0,
        le=1.0,
        description=(
            "Fraction of simulated OU paths that cross the adverse stop threshold "
            "|z| >= 4.0 within the horizon (higher = riskier)"
        ),
    )
    simulation_notes: Optional[str] = Field(
        default=None,
        description=(
            "Quantitative summary of Monte Carlo path diagnostics including half-life, "
            "convergence probability, breach probability, and recommended decision basis"
        ),
    )


class BatchSignalRequest(BaseModel):
    """Batch of signals for backtest or historical evaluation."""

    signals: List[SignalRequest] = Field(
        ...,
        description="List of signals to evaluate in bulk",
    )


class BatchGatekeeperResponse(BaseModel):
    """Batch evaluation response mapping signal indices to decisions."""

    results: List[GatekeeperResponse] = Field(
        ...,
        description="Aligned list of Gatekeeper responses corresponding to input signals",
    )
    total_evaluated: int
    bypassed_by_prefilter: int
    veto_count: int
    go_count: int


class MonteCarloSimulationRequest(BaseModel):
    """Request payload for running Ornstein-Uhlenbeck spread stress-testing."""

    ticker_a: str = Field(..., min_length=1, max_length=10, description="First leg ticker")
    ticker_b: str = Field(..., min_length=1, max_length=10, description="Second leg ticker")
    as_of_timestamp: datetime = Field(..., description="Point-in-time cutoff date/time (UTC)")
    lookback_days: int = Field(default=252, ge=60, le=1000, description="Trailing trading days for OU calibration")
    horizon_days: int = Field(default=10, ge=1, le=60, description="Forward simulation horizon in trading days")
    num_simulations: int = Field(default=1000, ge=100, le=10000, description="Number of Monte Carlo paths")

    @field_validator("ticker_a", "ticker_b")
    @classmethod
    def normalize_ticker(cls, v: str) -> str:
        return v.strip().upper().replace(".", "-")

    @field_validator("as_of_timestamp")
    @classmethod
    def ensure_tz(cls, v: datetime) -> datetime:
        from datetime import timezone
        if v.tzinfo is None:
            return v.replace(tzinfo=timezone.utc)
        return v


class MonteCarloSimulationResponse(BaseModel):
    """Response payload with quantitative path metrics from OU Monte Carlo simulation."""

    ticker_a: str
    ticker_b: str
    as_of: str
    probability_of_convergence: float
    breach_probability: float
    expected_max_drawdown_bps: float
    median_final_z: float
    half_life_days: float
    theta: float
    mu: float
    sigma_ou: float
    horizon_days: int
    num_simulations: int
    hedge_ratio_used: Optional[float] = None
    error: Optional[str] = None
